    [SqlFact]
    public async Task Approved_guest_script_produces_two_playable_owned_masters_captions_and_traceable_immutable_manifest()
    {
        using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await WatchTestFixture.Setup(s); var w = s.GetRequiredService<IWatchFactory>(); var request = WatchTestFixture.Request(f); var p = await w.CreateAsync(f.Context.Owner, f.Context.Universe, request, default); Assert.Equal(p.Id, (await w.CreateAsync(f.Context.Owner, f.Context.Universe, request, default)).Id); p = await WatchTestFixture.Drain(s, f, p.Id); Assert.Equal("Review", p.State); Assert.Equal(2, p.Artifacts.Length); Assert.Equal(f.Script.RevisionId, p.Timeline!.ScriptRevisionId); Assert.Equal(f.Script.Current!.Body, p.Timeline.Script); Assert.Equal(f.Character.CharacterId, p.Timeline.Cast.Single().Character.CharacterId); Assert.Equal(0, p.CreationCost); Assert.All(p.Stages.Where(x => x.Kind != "Approval"), x => Assert.Equal("Accepted", x.State));
        foreach (var a in p.Artifacts) { var preview = await w.PreviewAsync(f.Context.Owner, f.Context.Universe, a.Id, default); Assert.Equal("video/mp4", preview.Mime); Assert.Equal(a.Sha256, MediaRules.Hash(preview.Bytes)); }
        var media = s.GetRequiredService<IMediaLibrary>(); var imageBytes = (await media.ExportAsync(f.Context.Owner, f.Context.Universe, f.Image.Id, "Reuse", default)).Bytes; var voiceBytes = (await media.ExportAsync(f.Context.Owner, f.Context.Universe, f.Voice.Id, "Reuse", default)).Bytes; var binding = p.Snapshot.Profile.Configuration; var renderer = s.GetServices<IVideoRenderer>().Single(x => x.Key == binding.Renderer); var renderRequest = new WatchRenderRequest(p.Stages.Single(x => x.Kind == "RenderVertical").Id, binding.AccountReference, binding.Renderer, p.Timeline!, "Vertical", [new("scene-1", imageBytes, voiceBytes, null)]); Assert.Equal(p.Artifacts.Single(x => x.Aspect == "Vertical").Sha256, MediaRules.Hash((await renderer.SubmitAsync(renderRequest, default)).Master!)); await Assert.ThrowsAsync<RuntimeConflictException>(() => renderer.SubmitAsync(renderRequest with { Timeline = renderRequest.Timeline with { Title = "Changed original receipt" } }, default));
        await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.ExportAsync(f.Context.Owner, f.Context.Universe, p.Id, "Export", default)); await Assert.ThrowsAsync<EvidenceBlockedException>(() => new SourceRightsGuard(s.GetRequiredService<CoreDbContext>()).CheckAsync(f.Context.Owner, p.CoreRevisionId, new("Export", "en-IN", "IN", "Text"), default));
        await w.ReviewAsync(f.Context.Owner, f.Context.Universe, p.Id, new(Guid.NewGuid(), p.RowVersion, "Approve", "Fixture", "fixture:technical-only-human-release-pending", [], 2), default); var export = await w.ExportAsync(f.Context.Owner, f.Context.Universe, p.Id, "Export", default); Assert.Contains("WEBVTT", export.Vtt); Assert.Contains(f.Script.Current.Body, export.Srt); Assert.Equal(2, export.Production.ReviewMinutes); await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.ExportAsync(f.Context.Owner, f.Context.Universe, p.Id, "Publish", default));
        using var fresh = WatchTestFixture.Services(); using var again = fresh.CreateScope(); Assert.Equal(p.Artifacts[0].Sha256, MediaRules.Hash((await again.ServiceProvider.GetRequiredService<IWatchFactory>().PreviewAsync(f.Context.Owner, f.Context.Universe, p.Artifacts[0].Id, default)).Bytes));
        var db = s.GetRequiredService<CoreDbContext>(); db.ChangeTracker.Clear(); var row = await db.WatchProductions.SingleAsync(x => x.Id == p.Id); row.TimelineJson = "{}"; await Assert.ThrowsAsync<InvalidOperationException>(() => db.SaveChangesAsync());
    }
    [SqlFact]
    public async Task Known_render_failure_resumes_after_restart_without_repeating_accepted_media_or_timing()
    {
        using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await WatchTestFixture.Setup(s, "watch.fail-once.v1"); var w = s.GetRequiredService<IWatchFactory>(); var p = await w.CreateAsync(f.Context.Owner, f.Context.Universe, WatchTestFixture.Request(f), default); p = await WatchTestFixture.Drain(s, f, p.Id); Assert.Equal("Failed", p.State); var accepted = p.Stages.Where(x => x.State == "Accepted").Select(x => new { x.Id, x.Attempts }).ToArray();
        using var next = WatchTestFixture.Services(); using var nextScope = next.CreateScope(); var retry = nextScope.ServiceProvider.GetRequiredService<IWatchFactory>(); await retry.ControlAsync(f.Context.Owner, f.Context.Universe, p.Id, new(Guid.NewGuid(), p.RowVersion, "Resume", "fixture:known-pre-submission-failure"), default); p = await WatchTestFixture.Drain(nextScope.ServiceProvider, f, p.Id); if (p.State == "Failed") { await retry.ControlAsync(f.Context.Owner, f.Context.Universe, p.Id, new(Guid.NewGuid(), p.RowVersion, "Resume", "fixture:second-aspect-known-failure"), default); p = await WatchTestFixture.Drain(nextScope.ServiceProvider, f, p.Id); }
        Assert.Equal("Review", p.State); Assert.All(accepted, x => Assert.Equal(x.Attempts, p.Stages.Single(a => a.Id == x.Id).Attempts)); Assert.Equal(2, p.Artifacts.Length);
    }
    [SqlFact]
    public async Task Unknown_render_is_reconciled_at_original_binding_and_cannot_be_blindly_resubmitted()
    { using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await WatchTestFixture.Setup(s, "watch.unknown.v1"); var w = s.GetRequiredService<IWatchFactory>(); var p = await w.CreateAsync(f.Context.Owner, f.Context.Universe, WatchTestFixture.Request(f) with { Aspects = ["Vertical"] }, default); p = await WatchTestFixture.Drain(s, f, p.Id); Assert.Equal("Failed", p.State); Assert.Contains(p.Stages, x => x.State == "Unknown"); await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.ControlAsync(f.Context.Owner, f.Context.Universe, p.Id, new(Guid.NewGuid(), p.RowVersion, "Resume", "fixture:forbidden-retry"), default)); var reconcile = new WatchControl(Guid.NewGuid(), p.RowVersion, "Reconcile", "fixture:original-resource-only"); await w.ControlAsync(f.Context.Owner, f.Context.Universe, p.Id, reconcile, default); await w.ControlAsync(f.Context.Owner, f.Context.Universe, p.Id, reconcile, default); await Assert.ThrowsAsync<RuntimeConflictException>(() => w.ControlAsync(f.Context.Owner, f.Context.Universe, p.Id, reconcile with { EvidenceReference = "fixture:changed-replay" }, default)); p = await WatchTestFixture.Drain(s, f, p.Id); Assert.Equal("Review", p.State); Assert.Single(p.Artifacts); Assert.Equal(1, p.Stages.Single(x => x.Kind == "RenderVertical").Attempts); }
    [SqlFact]
    public async Task Wrong_scope_unapproved_cast_and_withdrawn_media_block_create_preview_and_snapshot_body()
    { using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await WatchTestFixture.Setup(s); var w = s.GetRequiredService<IWatchFactory>(); await Assert.ThrowsAsync<CoreAccessException>(() => w.CreateAsync(new(Guid.NewGuid(), f.Context.Owner.Actor), f.Context.Universe, WatchTestFixture.Request(f), default)); await Assert.ThrowsAsync<CoreAccessException>(() => w.CreateAsync(new(f.Context.Owner.TenantId, "m13-author"), f.Context.Universe, WatchTestFixture.Request(f), default)); var p = await w.CreateAsync(f.Context.Owner, f.Context.Universe, WatchTestFixture.Request(f), default); p = await WatchTestFixture.Drain(s, f, p.Id); var media = s.GetRequiredService<IMediaLibrary>(); var image = (await media.AssetsAsync(f.Context.Owner, f.Context.Universe, default)).SelectMany(x => x.Versions).Single(x => x.Id == f.Image.Id); await media.ReviewAsync(f.Context.Owner, f.Context.Universe, image.Id, new(Guid.NewGuid(), image.RowVersion, "Withdraw", "Fixture", "fixture:withdraw-reference", []), default); await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.PreviewAsync(f.Context.Owner, f.Context.Universe, p.Artifacts[0].Id, default)); var blocked = await w.InspectAsync(f.Context.Owner, f.Context.Universe, p.Id, default); Assert.Null(blocked.Timeline); Assert.Null(blocked.Snapshot.Script.Current); Assert.Empty(blocked.Snapshot.Cast); }
    [SqlFact]
    public async Task Second_renderer_preserves_owned_timeline_and_requires_its_own_final_review()
    { using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await WatchTestFixture.Setup(s); var w = s.GetRequiredService<IWatchFactory>(); var profile = await w.ProfileAsync(f.Context.Owner, f.Context.Universe, new(Guid.NewGuid(), "second-renderer", 1, "watch.ffmpeg.test-b.v1", "local:second-fixture", f.Template, 0, "INR", "Fixture", "fixture:second-renderer"), default); var p = await w.CreateAsync(f.Context.Owner, f.Context.Universe, WatchTestFixture.Request(f) with { ProfileId = profile, Aspects = ["Standard"] }, default); p = await WatchTestFixture.Drain(s, f, p.Id); Assert.Equal("Review", p.State); Assert.Single(p.Artifacts); Assert.Equal(f.Script.Current!.Body, p.Timeline!.Script); Assert.Equal(f.Presentation, p.Timeline.Cast.Single().Presentation.Id); Assert.Equal("watch.ffmpeg.test-b.v1", p.Snapshot.Profile.Configuration.Renderer); await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.ExportAsync(f.Context.Owner, f.Context.Universe, p.Id, "Export", default)); }
    [SqlFact]
    public async Task Cancelling_owner_fences_queued_media_admission_and_keeps_accepted_checkpoints()
    { using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await WatchTestFixture.Setup(s); var g = new RegistryTestFixture.Fixture(f.Context.Owner, f.Context.Universe, f.Context.Audience, f.Context.Bible, f.Context.Episode); var media = s.GetRequiredService<IMediaLibrary>(); var profile = await MediaTestFixture.Profile(s, g); var output = MediaTestFixture.Upload(g, f.Character, "watch-generated", []) with { ExpectedSha256 = "" }; var generation = new GenerateMedia(Guid.NewGuid(), profile, output, "Original preview", [f.Image.Id], [], 0); var r = WatchTestFixture.Request(f) with { Scenes = [WatchTestFixture.Request(f).Scenes[0] with { ImageVersionId = null, ImageGeneration = generation }] }; var w = s.GetRequiredService<IWatchFactory>(); var p = await w.CreateAsync(f.Context.Owner, f.Context.Universe, r, default); await w.ProcessNextAsync(default); await w.ProcessNextAsync(default); p = await w.InspectAsync(f.Context.Owner, f.Context.Universe, p.Id, default); Assert.Equal("Waiting", p.Stages.Single(x => x.Kind == "Assets").State); await w.ControlAsync(f.Context.Owner, f.Context.Universe, p.Id, new(Guid.NewGuid(), p.RowVersion, "Cancel", "fixture:cancel-owner"), default); await MediaTestFixture.Drain(s); var run = (await media.GenerationsAsync(f.Context.Owner, f.Context.Universe, default)).Single(x => x.Snapshot.Request.Admission?.ProductionId == p.Id); Assert.Equal("Failed", run.State); Assert.Null(run.AcceptedVersionId); Assert.Null(run.ExternalResourceId); Assert.Equal(0, run.ActualCost ?? 0); p = await w.InspectAsync(f.Context.Owner, f.Context.Universe, p.Id, default); Assert.Equal("Cancelled", p.State); Assert.Equal("Accepted", p.Stages.Single(x => x.Kind == "Storyboard").State); }
    [SqlFact]
    public async Task Actual_http_player_range_captions_roles_headers_and_scope_are_enforced()
    {
        using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await WatchTestFixture.Setup(s, actor: "integration-test-Administrator"); var w = s.GetRequiredService<IWatchFactory>(); var p = await w.CreateAsync(f.Context.Owner, f.Context.Universe, WatchTestFixture.Request(f) with { Aspects = ["Vertical"] }, default); p = await WatchTestFixture.Drain(s, f, p.Id); Assert.Equal("Review", p.State);
        using var app = new Microsoft.AspNetCore.Mvc.Testing.WebApplicationFactory<GeetaStudio.Api.ApiAssemblyMarker>().WithWebHostBuilder(b => { b.UseEnvironment("Development").ConfigureAppConfiguration((_, c) => c.AddInMemoryCollection(new Dictionary<string, string?> { ["Runtime:Enabled"] = "true", ["ConnectionStrings:ContentOS"] = LessonTestFixture.Connection, ["Staff:Administrator:0"] = f.Context.Owner.Actor, ["Staff:Reader:0"] = "integration-test-Reader", ["Watch:WorkerEnabled"] = "false", ["Media:WorkerEnabled"] = "false", ["Factory:WorkerEnabled"] = "false", ["Trends:RecheckWorkerEnabled"] = "false", ["Read:RetentionWorkerEnabled"] = "false", ["Knowledge:IndexWorkerEnabled"] = "false", ["Workflows:WorkerEnabled"] = "false", ["Assets:Root"] = Path.Combine(ArchitectureTests.RepositoryRoot, ".local", "test-assets"), ["Assets:Stores:watch"] = Path.Combine(ArchitectureTests.RepositoryRoot, ".local", "watch-test-masters") })); b.ConfigureServices(TestAuthentication.Configure); }); using var client = app.CreateClient(); var path = $"/api/v1/watch/tenants/{f.Context.Owner.TenantId}/universes/{f.Context.Universe}"; Assert.Equal(System.Net.HttpStatusCode.Unauthorized, (await client.GetAsync("/staff/watch")).StatusCode); client.DefaultRequestHeaders.Add("X-Test-Role", "Reader"); var page = await client.GetAsync("/staff/watch"); Assert.Equal(System.Net.HttpStatusCode.OK, page.StatusCode); Assert.Contains("noindex", page.Headers.GetValues("X-Robots-Tag")); using var request = new HttpRequestMessage(HttpMethod.Get, path + "/artifacts/" + p.Artifacts[0].Id + "/preview"); request.Headers.Range = new(0, 99); var preview = await client.SendAsync(request); Assert.True(preview.StatusCode == System.Net.HttpStatusCode.PartialContent, await preview.Content.ReadAsStringAsync()); Assert.True(preview.Headers.CacheControl!.NoStore); Assert.Equal("video/mp4", preview.Content.Headers.ContentType!.MediaType); Assert.Equal(100, (await preview.Content.ReadAsByteArrayAsync()).Length); Assert.Contains("WEBVTT", await client.GetStringAsync(path + "/productions/" + p.Id + "/captions.vtt")); Assert.Equal(System.Net.HttpStatusCode.Forbidden, (await client.GetAsync(path.Replace(f.Context.Owner.TenantId.ToString(), Guid.NewGuid().ToString()) + "/productions")).StatusCode); var control = new WatchControl(Guid.NewGuid(), p.RowVersion, "Cancel", "fixture:http-cancel"); Assert.Equal(System.Net.HttpStatusCode.Forbidden, (await client.PostAsJsonAsync(path + "/productions/" + p.Id + "/control", control)).StatusCode); client.DefaultRequestHeaders.Remove("X-Test-Role"); client.DefaultRequestHeaders.Add("X-Test-Role", "Administrator"); Assert.Equal(System.Net.HttpStatusCode.BadRequest, (await client.PostAsJsonAsync(path + "/productions/" + p.Id + "/control", control)).StatusCode); client.DefaultRequestHeaders.Add("X-ContentOS-Staff", "1"); Assert.Equal(System.Net.HttpStatusCode.NoContent, (await client.PostAsJsonAsync(path + "/productions/" + p.Id + "/control", control)).StatusCode);
    }
    [SqlFact]
    public async Task Synthetic_trend_guest_uses_same_pipeline_and_preserves_evidence_labels_and_cast_after_edit()
    {
        using var root = WatchTestFixture.Services(); using var scope = root.CreateScope(); var s = scope.ServiceProvider; var f = await TrendTestFixture.Setup(s, "m17-trend-owner", video: true); var db = s.GetRequiredService<CoreDbContext>(); var registry = s.GetRequiredService<IUniverseRegistry>(); var media = s.GetRequiredService<IMediaLibrary>(); var trends = s.GetRequiredService<ITrendWorkbench>(); var match = await TrendTestFixture.Match(s, f); var trend = await TrendTestFixture.Package(s, f, match); await trends.ReviewStoryAsync(f.Owner, f.Universe, trend.Id, new(Guid.NewGuid(), trend.RowVersion, "Approve", "Fixture", "fixture:synthetic-trend-not-reporting"), default);
        var c = (await registry.CharactersAsync(f.Owner, f.Universe, default)).Single(x => x.CharacterId == f.ChildCharacter); var g = new RegistryTestFixture.Fixture(f.Owner, f.Universe, f.ChildAudience, f.Bible, f.Episode); var image = await media.ImportAsync(f.Owner, f.Universe, MediaTestFixture.Upload(g, c, "trend-sheet", ContentOS.Integrations.MediaFiles.ReferenceCard(c.Profile.Rules.VisualAnchor, [])), default); await MediaTestFixture.Review(s, g, image); var voice = await media.ImportAsync(f.Owner, f.Universe, MediaTestFixture.Upload(g, c, "trend-tone", WatchTestFixture.Voice(12), "Voice"), default); await MediaTestFixture.Review(s, g, voice); var package = await MediaTestFixture.Package(s, g, c, image, voice); var presentation = await media.BindPackageAsync(f.Owner, f.Universe, package.Id, Guid.NewGuid(), default); await RegistryTestFixture.Review(s, f.Owner, f.Universe, presentation);
        var subject = await db.Subjects.Where(x => x.UniverseId == f.Universe).Select(x => x.Id).FirstAsync(); var context = new EditorialTestFixture.Fixture(f.Owner, f.Universe, f.ChildAudience, subject, f.Bible, f.Episode); var body = "Verified factual context (separate from the story):\n" + TrendTestFixture.Fact + "\nOriginal fictional analogy; not a portrayal of real people/events:\nA new guest pauses to check the setting."; var request = EditorialTestFixture.Request(context, "watch-trend") with { Draft = EditorialTestFixture.Request(context).Draft! with { Body = body } }; var editor = s.GetRequiredService<IEditorialWorkbench>(); var packet = await editor.StartAsync(f.Owner, f.Universe, request, default); await trends.BindAsync(f.Owner, f.Universe, new(Guid.NewGuid(), trend.Id, packet.Id), default); var episode = (await registry.EpisodesAsync(f.Owner, f.Universe, default)).Single(x => x.Id == f.Episode); var brief = RegistryTestFixture.Brief(g) with { PinnedChoices = [new(c.CharacterId, "Lead", presentation)], Budget = new(2, 0, "INR", true) }; await registry.ComposeAsync(f.Owner, f.Universe, new(Guid.NewGuid(), episode.RowVersion, brief, "None", [new(c.CharacterId, "FictionalDialogue", body, ["curious"], [], true)], [], ContentRevisionId: packet.RevisionId), default); packet = await EditorialTestFixture.Approved(s, context, await editor.InspectAsync(f.Owner, f.Universe, packet.Id, default));
        var w = s.GetRequiredService<IWatchFactory>(); var template = await w.TemplateAsync(f.Owner, f.Universe, new(Guid.NewGuid(), "trend-layout", 1, new()), default); var tv = (await w.TemplatesAsync(f.Owner, f.Universe, default)).Single(x => x.Id == template); await w.ReviewTemplateAsync(f.Owner, f.Universe, template, new(Guid.NewGuid(), tv.RowVersion, "Approve", "Fixture", "fixture:layout", [], 1), default); var profile = await w.ProfileAsync(f.Owner, f.Universe, new(Guid.NewGuid(), "trend-renderer", 1, "watch.ffmpeg.v1", "local:trend-fixture", template, 0, "INR", "Fixture", "fixture:trend-composition"), default); var inputs = new List<WatchSceneInput>(); for (var offset = 0; offset < body.Length;) { var length = Math.Min(150, body.Length - offset); inputs.Add(new("trend-" + inputs.Count, offset, length, c.CharacterId, presentation, image.Id, voice.Id, "fixture:tone-not-spoken-transcript")); offset += length; }
        var create = new CreateWatch(Guid.NewGuid(), "trend-episode", 1, packet.Id, profile, inputs.ToArray(), ["Standard"], 0, 600, trend.Id); await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.CreateAsync(f.Owner, f.Universe, create with { TrendBriefId = null }, default)); var p = await w.CreateAsync(f.Owner, f.Universe, create, default); var fixture = new WatchTestFixture.Fixture(context, c, packet, image, voice, presentation, template, profile); p = await WatchTestFixture.Drain(s, fixture, p.Id); Assert.Equal("Review", p.State); Assert.Single(p.Artifacts); Assert.NotNull(p.Timeline!.Trend); Assert.Contains("fictional", p.Timeline.EventLabel); Assert.Equal(f.ChildCharacter, p.Timeline.Cast.Single().Character.CharacterId); Assert.All(f.NewsSources, id => Assert.Contains(id, p.Timeline.SourceSnapshotIds)); Assert.Contains(p.Timeline.Claims, x => x.Label == "NewsClaim"); await w.ReviewAsync(f.Owner, f.Universe, p.Id, new(Guid.NewGuid(), p.RowVersion, "Approve", "Fixture", "fixture:trend-human-release-pending", [], 1), default); await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.ExportAsync(f.Owner, f.Universe, p.Id, "Publish", default));
        var pinned = System.Text.Json.JsonSerializer.Serialize(p.Timeline.Cast); c = (await registry.CharactersAsync(f.Owner, f.Universe, default)).Single(x => x.CharacterId == c.CharacterId); await registry.ControlCharacterAsync(f.Owner, f.Universe, c.CharacterId, new(Guid.NewGuid(), c.RowVersion, "Retire", "fixture:later-edit"), default); var changed = await w.InspectAsync(f.Owner, f.Universe, p.Id, default); var saved = await db.WatchProductions.AsNoTracking().SingleAsync(x => x.Id == p.Id); Assert.Equal(pinned, System.Text.Json.JsonSerializer.Serialize(System.Text.Json.JsonSerializer.Deserialize<WatchSnapshot>(saved.SnapshotJson)!.Cast)); await Assert.ThrowsAsync<EvidenceBlockedException>(() => w.PreviewAsync(f.Owner, f.Universe, p.Artifacts[0].Id, default));
    }
